import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import java.io.File;
import java.util.*;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class LayoutConsistencyDetector extends Detector implements XmlScanner {

    public static final Issue ISSUE = Issue.create(
            "InconsistentLayout",
            "Inconsistent layout",
            "This layout file defines a different set of widgets in one or more configuration "
                    + "folders than other versions of the same layout. This means code that calls "
                    + "findViewById(...) may fail at runtime for those configurations.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(LayoutConsistencyDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private final Map<String, Map<String, Map<String, Set<String>>>> mProjectLayouts = new HashMap<>();

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mProjectLayouts.clear();
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
        File file = context.file;
        String layoutName = getBaseName(file.getName());
        String folderName = file.getParentFile().getName();
        String projectPath = context.getProject().getDir().getPath();

        Set<String> widgets = new HashSet<>();
        collectWidgets(document.getDocumentElement(), widgets);

        mProjectLayouts
            .computeIfAbsent(projectPath, k -> new HashMap<>())
            .computeIfAbsent(layoutName, k -> new HashMap<>())
            .put(folderName, widgets);
    }

    private void collectWidgets(Element element, Set<String> widgets) {
        if (element == null) return;
        String id = element.getAttributeNS(ANDROID_URI, ATTR_ID);
        String signature;
        if (id != null && !id.isEmpty()) {
            String idName = stripIdPrefix(id);
            signature = element.getTagName() + " [" + idName + "]";
        } else {
            signature = element.getTagName();
        }
        widgets.add(signature);

        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                collectWidgets((Element) child, widgets);
            }
            child = child.getNextSibling();
        }
    }

    private String stripIdPrefix(String id) {
        if (id.startsWith("@+id/")) return id.substring(5);
        if (id.startsWith("@id/")) return id.substring(4);
        return id;
    }

    private String getBaseName(String fileName) {
        int dot = fileName.lastIndexOf('.');
        return dot == -1 ? fileName : fileName.substring(0, dot);
    }

    @Override
    public void afterCheckRootProject(@NonNull Context context) {
        for (Map<String, Map<String, Set<String>>> layouts : mProjectLayouts.values()) {
            for (Map.Entry<String, Map<String, Set<String>>> layoutEntry : layouts.entrySet()) {
                String layoutName = layoutEntry.getKey();
                Map<String, Set<String>> versions = layoutEntry.getValue();
                if (versions.size() < 2) continue;

                Set<String> union = new HashSet<>();
                for (Set<String> widgets : versions.values()) union.addAll(widgets);

                if (union.isEmpty()) continue;

                for (Map.Entry<String, Set<String>> versionEntry : versions.entrySet()) {
                    String folderName = versionEntry.getKey();
                    Set<String> widgets = versionEntry.getValue();
                    Set<String> missing = new HashSet<>(union);
                    missing.removeAll(widgets);
                    if (!missing.isEmpty()) {
                        File file = findLayoutFile(context, layoutName, folderName);
                        if (file == null) continue;
                        Location location = Location.create(file);
                        String message = String.format(
                                "The layout '%1$s' has a different set of views in `%2$s`; "
                                        + "the following views are present in other configurations but not here: %3$s",
                                layoutName, folderName, sorted(missing));
                        context.report(ISSUE, location, message);
                    }
                }
            }
        }
    }

    private File findLayoutFile(@NonNull Context context, String layoutName, String folderName) {
        // We don't have a direct lookup; scan project resource folders.
        // Alternatively we could store file path in the map.
        return null; // placeholder
    }

    private String sorted(Set<String> set) {
        List<String> list = new ArrayList<>(set);
        Collections.sort(list);
        return list.toString();
    }
}
